const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);function show(html){$('resultado').innerHTML=html;$('resultado').hidden=false;$('resultado').focus();}function finish(){return '<div class="actions no-print"><button type="button" id="imprimir">Imprimir / guardar como PDF</button><a class="button secondary" href="https://wa.me/593978887392" target="_blank" rel="noopener">Consultar con TempoLegal ↗</a></div><p class="privacy">Al abrir WhatsApp usted decide qué compartir. Sus respuestas no se incorporan al enlace.</p>';}document.addEventListener('click',e=>{if(e.target.id==='imprimir')window.print();});document.querySelector('form').addEventListener('reset',()=>{$('resultado').hidden=true;});